import { locales, names, shortNames, home, journey } from '../config.mjs';

export function head(context, isJourney) {
  const { lang, content, esc } = context;
  return `<!doctype html>
<!-- Generated by npm run build. Edit src/templates/ and src/content/ instead. -->
<html lang="${lang}" dir="${content.dir}">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <meta name="theme-color" content="#193348">
  <meta name="description" content="${esc(content.ui.siteDescription)}">
  <title>Imad Chakir — ${esc(isJourney ? content.ui.journey : content.title)}</title>
  <link rel="icon" href="assets/img/favicon.svg" type="image/svg+xml">
  <link rel="stylesheet" href="assets/css/styles.css">
  ${locales.map(code => `<link rel="alternate" hreflang="${code}" href="${isJourney ? journey(code) : home(code)}">`).join('\n  ')}
  <script src="assets/js/main.js" defer></script>
  ${isJourney ? '<script src="assets/js/journey.js" defer></script>' : ''}
</head>`;
}

export function header(context, isJourney) {
  const { lang, ui, esc } = context;
  const prefix = isJourney ? home(lang) : '';
  return `<a class="skip-link" href="#main">${esc(ui.skip)}</a>
  <header class="site-header">
    <div class="shell header-inner">
      <a class="wordmark" href="${home(lang)}" aria-label="Imad Chakir"><span class="monogram" aria-hidden="true">ic.</span><bdi>Imad Chakir</bdi></a>
      <nav class="nav-links" id="nav-links" aria-label="${esc(ui.nav)}">
        ${['experience', 'projects', 'skills', 'contact'].map(key => `<a href="${prefix}#${key}">${esc(ui[key])}</a>`).join('\n        ')}
      </nav>
      <div class="header-controls">
        <nav class="language-switch" aria-label="${esc(ui.language)}">${locales.map(code => `<a href="${isJourney ? journey(code) : home(code)}" lang="${code}" hreflang="${code}" aria-label="${names[code]}"${code === lang ? ' aria-current="page"' : ''}>${shortNames[code]}</a>`).join('')}</nav>
        <button class="menu-toggle" aria-expanded="false" aria-controls="nav-links" hidden><span>${esc(ui.menu)}</span><span aria-hidden="true">☰</span></button>
      </div>
    </div>
  </header>`;
}

export function footer(context, isJourney = false) {
  const { lang, content, contact, esc } = context;
  return `<footer class="site-footer shell"><p><bdi>© ${contact.name}</bdi> · ${esc(content.location)}</p><a href="${isJourney ? home(lang) : '#home'}">${esc(isJourney ? content.ui.back : content.ui.top)} <span aria-hidden="true">${isJourney ? '↗' : '↑'}</span></a></footer>`;
}
